using System.Security.Claims;
using Core.Authorization;
using Core.Modules;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.DependencyInjection;
using Modules.Payroll.DTOs;
using Modules.Payroll.Repositories;
using Modules.Payroll.Services;
using Shared.Primitives.Identifiers;

namespace Modules.Payroll;

public static class PayrollModuleExtensions
{
    public static IServiceCollection AddPayrollModule(this IServiceCollection services)
    {
        services.AddSingleton<IModuleManifestProvider, PayrollModuleManifestProvider>();
        services.AddSingleton<PayrollRepository>();
        services.AddSingleton<PayrollService>();
        services.AddSingleton<PayrollCalculationEngine>();
        services.AddSingleton<IPayrollCountryProviderRegistry, PayrollCountryProviderRegistry>();
        return services;
    }

    public static WebApplication MapPayrollModule(this WebApplication app)
    {
        var group = app.MapGroup("/api/v1/payroll").WithTags("Payroll").RequireAuthorization().RequireRateLimiting("api");
        group.MapGet("/legal-entities/{legalEntityId:guid}/groups", async (Guid legalEntityId, HttpContext http, PayrollService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer auth, CancellationToken ct) => await Execute(http, subjects, auth, "payroll.group.read", legalEntityId, () => service.ListGroupsAsync(AccessTenant(http), legalEntityId, ct)));
        group.MapPost("/legal-entities/{legalEntityId:guid}/groups", async (Guid legalEntityId, CreatePayrollGroupRequest request, HttpContext http, PayrollService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer auth, CancellationToken ct) => request.LegalEntityId != legalEntityId ? Results.BadRequest(new { code = "payroll.entity_scope_invalid" }) : await Execute(http, subjects, auth, "payroll.group.manage", legalEntityId, () => service.CreateGroupAsync(AccessTenant(http), request, ct), StatusCodes.Status201Created));
        group.MapGet("/legal-entities/{legalEntityId:guid}/groups/{groupId:guid}/periods", async (Guid legalEntityId, Guid groupId, HttpContext http, PayrollService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer auth, CancellationToken ct) => await Execute(http, subjects, auth, "payroll.group.read", legalEntityId, () => service.ListPeriodsAsync(AccessTenant(http), legalEntityId, groupId, ct)));
        group.MapPost("/legal-entities/{legalEntityId:guid}/groups/{groupId:guid}/periods", async (Guid legalEntityId, Guid groupId, CreatePayrollPeriodRequest request, HttpContext http, PayrollService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer auth, CancellationToken ct) => request.PayrollGroupId != groupId ? Results.BadRequest(new { code = "payroll.group_scope_invalid" }) : await Execute(http, subjects, auth, "payroll.group.manage", legalEntityId, () => service.CreatePeriodAsync(AccessTenant(http), legalEntityId, request, ct), StatusCodes.Status201Created));
        group.MapGet("/legal-entities/{legalEntityId:guid}/runs", async (Guid legalEntityId, int? page, int? pageSize, HttpContext http, PayrollService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer auth, CancellationToken ct) => await Execute(http, subjects, auth, "payroll.run.read", legalEntityId, () => service.ListRunsAsync(AccessTenant(http), legalEntityId, page ?? 1, pageSize ?? 50, ct)));
        group.MapPost("/legal-entities/{legalEntityId:guid}/runs", async (Guid legalEntityId, CreatePayrollRunRequest request, HttpContext http, PayrollService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer auth, CancellationToken ct) => await Execute(http, subjects, auth, "payroll.run.create", legalEntityId, () => service.CreateRunAsync(AccessTenant(http), legalEntityId, request, ct), StatusCodes.Status201Created));
        group.MapGet("/legal-entities/{legalEntityId:guid}/runs/{runId:guid}", async (Guid legalEntityId, Guid runId, HttpContext http, PayrollService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer auth, CancellationToken ct) => await Execute(http, subjects, auth, "payroll.run.read", legalEntityId, async () => await service.GetRunAsync(AccessTenant(http), legalEntityId, runId, ct) ?? throw new PayrollRepositoryException("payroll.run_not_found")));
        group.MapGet("/legal-entities/{legalEntityId:guid}/runs/{runId:guid}/employees", async (Guid legalEntityId, Guid runId, HttpContext http, PayrollService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer auth, CancellationToken ct) => await Execute(http, subjects, auth, "payroll.run.review", legalEntityId, () => service.ListRunEmployeesAsync(AccessTenant(http), legalEntityId, runId, ct)));
        group.MapPost("/legal-entities/{legalEntityId:guid}/runs/{runId:guid}/calculate", async (Guid legalEntityId, Guid runId, HttpContext http, PayrollService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer auth, CancellationToken ct) => await Execute(http, subjects, auth, "payroll.run.calculate", legalEntityId, async () => { await service.CalculateRunAsync(AccessTenant(http), legalEntityId, runId, ct); return new { status = "Calculated" }; }));
        group.MapPost("/legal-entities/{legalEntityId:guid}/runs/{runId:guid}/capture-inputs", async (Guid legalEntityId, Guid runId, HttpContext http, PayrollService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer auth, CancellationToken ct) => await Execute(http, subjects, auth, "payroll.run.capture_inputs", legalEntityId, () => service.CaptureInputsAsync(AccessTenant(http), legalEntityId, runId, ct)));
        group.MapPost("/legal-entities/{legalEntityId:guid}/runs/{runId:guid}/finalize", async (Guid legalEntityId, Guid runId, HttpContext http, PayrollService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer auth, CancellationToken ct) => await Execute(http, subjects, auth, "payroll.run.finalize", legalEntityId, async () => { await service.FinalizeRunAsync(AccessTenant(http), legalEntityId, runId, ct); return new { status = "Finalized" }; }));
        group.MapGet("/legal-entities/{legalEntityId:guid}/payslips", async (Guid legalEntityId, HttpContext http, PayrollService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer auth, CancellationToken ct) => await Execute(http, subjects, auth, "payroll.payslip.read", legalEntityId, () => service.ListPayslipsAsync(AccessTenant(http), legalEntityId, ct)));
        group.MapPost("/legal-entities/{legalEntityId:guid}/inputs", async (Guid legalEntityId, CreatePayrollInputRequest request, HttpContext http, PayrollService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer auth, CancellationToken ct) => request.LegalEntityId != legalEntityId ? Results.BadRequest(new { code = "payroll.entity_scope_invalid" }) : await Execute(http, subjects, auth, "payroll.input.create", legalEntityId, () => service.CreateInputAsync(AccessTenant(http), request, ct), StatusCodes.Status201Created));
        group.MapPost("/legal-entities/{legalEntityId:guid}/inputs/{inputId:guid}/approve", async (Guid legalEntityId, Guid inputId, HttpContext http, PayrollService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer auth, CancellationToken ct) => await Execute(http, subjects, auth, "payroll.input.approve", legalEntityId, () => service.ApproveInputAsync(AccessTenant(http), legalEntityId, inputId, ct)));
        group.MapPost("/legal-entities/{legalEntityId:guid}/employee-receivables", async (Guid legalEntityId, CreateReceivableRequest request, HttpContext http, PayrollService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer auth, CancellationToken ct) => request.LegalEntityId != legalEntityId ? Results.BadRequest(new { code = "payroll.entity_scope_invalid" }) : await Execute(http, subjects, auth, "payroll.loan.create", legalEntityId, () => service.CreateReceivableAsync(AccessTenant(http), request, ct), StatusCodes.Status201Created));
        group.MapPost("/legal-entities/{legalEntityId:guid}/employee-receivables/{receivableId:guid}/approve", async (Guid legalEntityId, Guid receivableId, HttpContext http, PayrollService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer auth, CancellationToken ct) => await Execute(http, subjects, auth, "payroll.loan.approve", legalEntityId, () => service.ApproveReceivableAsync(AccessTenant(http), legalEntityId, receivableId, ct)));
        group.MapPost("/legal-entities/{legalEntityId:guid}/employee-receivables/{receivableId:guid}/disburse", async (Guid legalEntityId, Guid receivableId, HttpContext http, PayrollService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer auth, CancellationToken ct) => await Execute(http, subjects, auth, "payroll.payment.prepare", legalEntityId, () => service.RequestReceivableDisbursementAsync(AccessTenant(http), legalEntityId, receivableId, ct)));
        group.MapPost("/legal-entities/{legalEntityId:guid}/employee-receivables/disbursements/{disbursementId:guid}/complete", async (Guid legalEntityId, Guid disbursementId, string? providerReference, HttpContext http, PayrollService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer auth, CancellationToken ct) => await Execute(http, subjects, auth, "payroll.payment.prepare", legalEntityId, () => service.CompleteReceivableDisbursementAsync(AccessTenant(http), legalEntityId, disbursementId, providerReference, ct)));
        group.MapPost("/legal-entities/{legalEntityId:guid}/employee-receivables/disbursements/{disbursementId:guid}/fail", async (Guid legalEntityId, Guid disbursementId, string? failureCode, HttpContext http, PayrollService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer auth, CancellationToken ct) => await Execute(http, subjects, auth, "payroll.payment.prepare", legalEntityId, () => service.FailReceivableDisbursementAsync(AccessTenant(http), legalEntityId, disbursementId, failureCode, ct)));
        group.MapGet("/legal-entities/{legalEntityId:guid}/settings/statutory", async (Guid legalEntityId, HttpContext http, PayrollService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer auth, CancellationToken ct) => await Execute(http, subjects, auth, "payroll.settings.read", legalEntityId, () => service.GetStatutorySettingsAsync(AccessTenant(http), legalEntityId, ct)));
        group.MapGet("/legal-entities/{legalEntityId:guid}/settings/statutory/history", async (Guid legalEntityId, HttpContext http, PayrollService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer auth, CancellationToken ct) => await Execute(http, subjects, auth, "payroll.settings.read", legalEntityId, () => service.ListStatutorySettingsHistoryAsync(AccessTenant(http), legalEntityId, ct)));
        group.MapPut("/legal-entities/{legalEntityId:guid}/settings/statutory", async (Guid legalEntityId, UpdatePayrollStatutorySettingsRequest request, HttpContext http, PayrollService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer auth, CancellationToken ct) => await Execute(http, subjects, auth, "payroll.settings.manage", legalEntityId, () => service.UpdateStatutorySettingsAsync(AccessTenant(http), legalEntityId, Guid.Parse(http.User.FindFirstValue(ClaimTypes.NameIdentifier)!), request, ct)));
        return app;
    }

    private static TenantId AccessTenant(HttpContext http) => new(Guid.Parse(http.User.FindFirstValue("tenant_id")!));
    private static async Task<IResult> Execute<T>(HttpContext http, IAuthorizationSubjectStore subjects, IPermissionAuthorizer auth, string permission, Guid entity, Func<Task<T>> action, int status = 200)
    {
        if (!Guid.TryParse(http.User.FindFirstValue("tenant_id"), out var tenantId) || !Guid.TryParse(http.User.FindFirstValue("membership_id"), out var membershipId)) return Results.Unauthorized();
        var tenant = new TenantId(tenantId); var subject = await subjects.LoadAsync(tenant, membershipId, http.RequestAborted); if (subject is null) return Results.Unauthorized(); if (!auth.Authorize(subject, permission, PermissionScope.ForLegalEntity(tenant, new(entity)))) return Results.Forbid();
        try { var result = await action(); return status == 201 ? Results.Created(http.Request.Path, result) : Results.Ok(result); } catch (PayrollRepositoryException ex) { return Results.Problem(statusCode: ex.Code.Contains("not_found") ? 404 : ex.Code.Contains("duplicate") || ex.Code.Contains("finalized") ? 409 : 400, title: ex.Code, extensions: new Dictionary<string, object?> { ["code"] = ex.Code }); }
    }
}

