 "platform.iam", "platform.audit", "platform.transaction-coordination"]), new(["PayrollFinalizedV1", "PayrollPaymentRequestedV1"], ["PaymentCompletedV1", "PaymentCancelledV1"]), new(true, "blocked_if_dependents"));
}
